// Generated by build.sh from src/ - do not edit by hand.
import { definePterodactylExtension } from '@pterodactyl/sdk';
const CSS = `/*
 * Orbital - token overrides for the Pterodactyl v2 panel.
 * Only CSS custom properties here, scoped to :root.dark and NOT inside @layer
 * (same rules as the official Dark Theme, otherwise the panel's values win).
 * After editing: run ./build.sh, bump "version" in extension/extension.json, push.
 */
:root.dark {
    /* Surfaces */
    --background: #110e0b;
    --card: #211c18;
    --muted: #1a1511;
    --popover: #2a231d;
    --secondary: #2c251f;
    --sunken: color-mix(in oklab, var(--card) 78%, black);

    /* Text */
    --foreground: #f3ece2;
    --card-foreground: var(--foreground);
    --popover-foreground: var(--foreground);
    --secondary-foreground: var(--foreground);
    --muted-foreground: #a99d8f;

    /* Brand (light fills + dark ink so they pass contrast as fill AND as text) */
    --primary: #e0913c;
    --primary-foreground: #1a120a;
    --accent: #e0913c;
    --accent-foreground: #1a120a;
    --ring: #e0913c;

    /* Lines and forms */
    --border: #342c25;
    --input: #3a3129;

    /* Status */
    --destructive: #f0736b;
    --destructive-foreground: #1a0a09;
    --success: #5cc48a;
    --success-foreground: #08140d;
    --warning: #f0b43c;
    --warning-foreground: #1a1204;

    /* Charts and avatars */
    --chart-1: #e0913c;
    --chart-2: #d6e07b;
    --chart-3: #5cc48a;
    --chart-4: #58a6e8;
    --chart-5: #c98be0;

    /* Shape */
    --radius: 0.75rem;

    /* Console */
    --terminal-background: #0c0a08;
    --terminal-selection: #4a3720;
    --terminal-selection-foreground: #ffffff;
    --terminal-ansi-black: #2a231d;
    --terminal-ansi-red: #f0736b;
    --terminal-ansi-green: #5cc48a;
    --terminal-ansi-yellow: #e0913c;
    --terminal-ansi-blue: #58a6e8;
    --terminal-ansi-magenta: #c98be0;
    --terminal-ansi-cyan: #5cc4c4;
    --terminal-ansi-white: #e8dfd3;
    --terminal-ansi-bright-black: #5b5148;
    --terminal-ansi-bright-red: #ff8f87;
    --terminal-ansi-bright-green: #7be0a8;
    --terminal-ansi-bright-yellow: #f5b062;
    --terminal-ansi-bright-blue: #7cc0f5;
    --terminal-ansi-bright-magenta: #e0a8f0;
    --terminal-ansi-bright-cyan: #7de0e0;
    --terminal-ansi-bright-white: #ffffff;
}

/* Small extras (plain CSS, safe to delete) */
::selection { background: #e0913c; color: #1a120a; }
html.dark * { scrollbar-color: #3a3129 transparent; scrollbar-width: thin; }

/* Orbital look: warm glow, crisp type, amber focus */
html.dark body {
    background-image:
        radial-gradient(1100px 560px at 88% -8%, rgba(224, 145, 60, 0.12), transparent 60%),
        radial-gradient(900px 480px at -8% 108%, rgba(214, 224, 123, 0.05), transparent 60%);
    background-attachment: fixed;
    -webkit-font-smoothing: antialiased;
}
html.dark h1, html.dark h2, html.dark h3 { letter-spacing: -0.015em; }
html.dark button:focus-visible, html.dark a:focus-visible, html.dark input:focus-visible,
html.dark select:focus-visible, html.dark textarea:focus-visible, html.dark [role="button"]:focus-visible,
html.dark [role="tab"]:focus-visible, html.dark [role="switch"]:focus-visible { outline: 2px solid #e0913c; outline-offset: 2px; }
/* never outline big containers that only receive programmatic focus */
html.dark [tabindex="-1"]:focus, html.dark [tabindex="-1"]:focus-visible, html.dark main:focus-visible, html.dark #app:focus-visible { outline: none !important; }
html.dark button, html.dark a { transition: background-color .15s ease, color .15s ease, border-color .15s ease, box-shadow .2s ease; }
html.dark button:hover:not(:disabled) { box-shadow: 0 0 0 1px rgba(224, 145, 60, 0.35), 0 6px 22px rgba(224, 145, 60, 0.12); }
@media (prefers-reduced-motion: reduce) {
    html.dark button, html.dark a { transition: none; }
}`;

// 1) Theme tokens, injected once at module load.
(function () {
    if (typeof document === 'undefined') return;
    var id = 'orbital-theme-css';
    var el = document.getElementById(id);
    if (!el) { el = document.createElement('style'); el.id = id; document.head.appendChild(el); }
    el.textContent = CSS;
})();

// 2) React comes from the panel's import map. If it is missing, only the
//    React features are skipped - the theme and palette keep working.
var R = null;
try { var __r = await import('react'); R = __r.default && __r.default.createElement ? __r.default : __r; } catch (e) { console.warn('[orbital] react unavailable, favourites disabled'); }

// Ctrl/Cmd + K command palette: servers and pages. Vanilla DOM, uses panel tokens.
(function () {
    if (typeof document === 'undefined' || window.__orbitalPalette) return;
    window.__orbitalPalette = true;

    var PAGES = [
        { label: 'Home', hint: 'PANEL', href: '/' },
        { label: 'Your account', hint: 'ACCOUNT', href: '/account' },
        { label: 'Administration', hint: 'ADMIN', href: '/panel' },
    ];
    var STYLE = [
        '.orb-pal-back{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.55);backdrop-filter:blur(3px);display:flex;align-items:flex-start;justify-content:center;padding-top:14vh}',
        '.orb-pal{width:min(560px,92vw);background:var(--popover);color:var(--popover-foreground);border:1px solid var(--border);border-radius:var(--radius);box-shadow:0 24px 70px rgba(0,0,0,.6),0 0 0 1px rgba(224,145,60,.12);overflow:hidden;font-family:inherit}',
        '.orb-pal input{width:100%;box-sizing:border-box;padding:14px 16px;background:transparent;color:inherit;border:0;border-bottom:1px solid var(--border);outline:none;font-size:15px}',
        '.orb-pal input:focus{box-shadow:inset 0 -2px 0 var(--primary)}',
        '.orb-pal ul{list-style:none;margin:0;padding:6px;max-height:340px;overflow:auto}',
        '.orb-pal li{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:10px 12px;border-radius:calc(var(--radius) - 4px);cursor:pointer;font-size:14px}',
        '.orb-pal li small{font-size:10px;letter-spacing:.08em;color:var(--muted-foreground)}',
        '.orb-pal li.on{background:color-mix(in oklab,var(--primary) 18%,transparent);box-shadow:inset 3px 0 0 var(--primary)}',
        '.orb-pal .orb-sec{padding:8px 12px 4px;font-size:10px;letter-spacing:.1em;color:var(--muted-foreground)}',
        '.orb-pal .orb-foot{display:flex;gap:14px;padding:8px 14px;border-top:1px solid var(--border);font-size:11px;color:var(--muted-foreground)}',
    ].join('\n');

    var st = document.createElement('style');
    st.textContent = STYLE;
    document.head.appendChild(st);

    var servers = [], loadedAt = 0, root = null, input = null, list = null, rows = [], idx = 0;

    function loadServers() {
        if (Date.now() - loadedAt < 60000) return;
        loadedAt = Date.now();
        fetch('/api/client?per_page=100', { credentials: 'same-origin', headers: { Accept: 'application/json' } })
            .then(function (r) { return r.ok ? r.json() : null; })
            .then(function (j) {
                if (!j || !j.data) return;
                var favs = [];
                try { favs = JSON.parse(localStorage.getItem('orbital:favs') || '[]'); } catch (e) {}
                servers = j.data.map(function (s) {
                    var a = s.attributes || {};
                    var f = favs.indexOf(a.identifier) !== -1;
                    return { label: a.name || a.identifier, hint: f ? '\u2605 SERVER' : 'SERVER', fav: f, href: '/server/' + (a.identifier || '') };
                }).filter(function (s) { return s.href !== '/server/'; })
                  .sort(function (x, y) { return (y.fav ? 1 : 0) - (x.fav ? 1 : 0); });
                if (root) render();
            })
            .catch(function () {});
    }

    function render() {
        var q = input.value.trim().toLowerCase();
        var all = servers.concat(PAGES);
        rows = all.filter(function (i) { return !q || i.label.toLowerCase().indexOf(q) !== -1; });
        if (idx >= rows.length) idx = Math.max(0, rows.length - 1);
        list.textContent = '';
        if (!rows.length) {
            var none = document.createElement('div');
            none.className = 'orb-sec';
            none.textContent = 'NO RESULTS';
            list.appendChild(none);
            return;
        }
        rows.forEach(function (item, n) {
            var li = document.createElement('li');
            if (n === idx) li.className = 'on';
            var a = document.createElement('span');
            a.textContent = item.label;
            var b = document.createElement('small');
            b.textContent = item.hint;
            li.appendChild(a); li.appendChild(b);
            li.addEventListener('mousemove', function () { if (idx !== n) { idx = n; render(); } });
            li.addEventListener('click', function () { go(item); });
            list.appendChild(li);
        });
        var cur = list.querySelector('.on');
        if (cur && cur.scrollIntoView) cur.scrollIntoView({ block: 'nearest' });
    }

    function go(item) { close(); window.location.assign(item.href); }

    function close() { if (root) { root.remove(); root = null; } }

    function open() {
        if (root) return;
        loadServers();
        idx = 0;
        root = document.createElement('div');
        root.className = 'orb-pal-back';
        root.addEventListener('mousedown', function (e) { if (e.target === root) close(); });
        var box = document.createElement('div');
        box.className = 'orb-pal';
        input = document.createElement('input');
        input.type = 'text';
        input.placeholder = 'Search servers or pages...';
        input.setAttribute('aria-label', 'Search servers or pages');
        input.addEventListener('input', function () { idx = 0; render(); });
        list = document.createElement('ul');
        var foot = document.createElement('div');
        foot.className = 'orb-foot';
        foot.textContent = '\u2191\u2193 navigate    \u21b5 open    esc close';
        box.appendChild(input); box.appendChild(list); box.appendChild(foot);
        root.appendChild(box);
        document.body.appendChild(root);
        render();
        input.focus();
    }

    document.addEventListener('keydown', function (e) {
        if ((e.ctrlKey || e.metaKey) && !e.shiftKey && !e.altKey && e.key && e.key.toLowerCase() === 'k') {
            e.preventDefault();
            root ? close() : open();
            return;
        }
        if (!root) return;
        if (e.key === 'Escape') { e.preventDefault(); close(); }
        else if (e.key === 'ArrowDown') { e.preventDefault(); if (rows.length) { idx = (idx + 1) % rows.length; render(); } }
        else if (e.key === 'ArrowUp') { e.preventDefault(); if (rows.length) { idx = (idx - 1 + rows.length) % rows.length; render(); } }
        else if (e.key === 'Enter') { e.preventDefault(); if (rows[idx]) go(rows[idx]); }
    }, true);
})();

// Favourites: star button next to each server name on the dashboard (slot
// dashboard.serverRow.name.after). Stored per browser in localStorage.
// Favourites float to the top of the server list.
var FAV_KEY = 'orbital:favs';
function favList() {
    try { var v = JSON.parse(localStorage.getItem(FAV_KEY) || '[]'); return Array.isArray(v) ? v : []; } catch (e) { return []; }
}
function isFav(id) { return favList().indexOf(id) !== -1; }
function toggleFav(id) {
    var l = favList(), i = l.indexOf(id);
    if (i === -1) l.push(id); else l.splice(i, 1);
    try { localStorage.setItem(FAV_KEY, JSON.stringify(l)); } catch (e) {}
    window.dispatchEvent(new Event('orbital-favs'));
}

var orderTimer = 0;
function scheduleOrder() {
    clearTimeout(orderTimer);
    orderTimer = setTimeout(applyOrder, 60);
}
function applyOrder() {
    var stars = [].slice.call(document.querySelectorAll('[data-orb-fav]'));
    if (stars.length < 2) { stars.forEach(function (s) { /* single card: nothing to reorder */ }); return; }
    var box = stars[0].parentElement;
    while (box && !stars.every(function (s) { return box.contains(s); })) box = box.parentElement;
    if (!box) return;
    var d = getComputedStyle(box).display;
    if (d.indexOf('flex') === -1 && d.indexOf('grid') === -1) return;
    stars.forEach(function (st) {
        var c = st;
        while (c.parentElement && c.parentElement !== box) c = c.parentElement;
        if (c === st) return;
        c.style.order = st.getAttribute('data-orb-fav') === '1' ? '-1' : '';
    });
}

function OrbitalStar(props) {
    var data = props && props.data;
    var id = data && data.attributes ? data.attributes.identifier : null;
    var st = R.useState(id ? isFav(id) : false), fav = st[0], setFav = st[1];
    R.useEffect(function () {
        function h() { setFav(id ? isFav(id) : false); scheduleOrder(); }
        window.addEventListener('orbital-favs', h);
        scheduleOrder();
        return function () { window.removeEventListener('orbital-favs', h); scheduleOrder(); };
    }, [id]);
    if (!id) return null;
    return R.createElement('button', {
        type: 'button',
        'data-orb-fav': fav ? '1' : '0',
        'aria-pressed': fav,
        'aria-label': fav ? 'Remove from favourites' : 'Add to favourites',
        title: fav ? 'Remove from favourites' : 'Add to favourites',
        onClick: function (e) { e.preventDefault(); e.stopPropagation(); toggleFav(id); },
        style: {
            marginLeft: '8px', background: 'transparent', border: '0', cursor: 'pointer',
            fontSize: '16px', lineHeight: '1', padding: '2px 4px',
            color: fav ? '#e0913c' : 'var(--muted-foreground)',
        },
    }, fav ? '\u2605' : '\u2606');
}

export default definePterodactylExtension({
    setup(ctx) {
        try {
            if (R && ctx && ctx.slots) ctx.slots.register('dashboard.serverRow.name.after', OrbitalStar);
        } catch (e) {
            console.warn('[orbital] favourites disabled:', e);
        }
    },
});
